window.kbPageData["views/practice/s-599008555ed60dda"] = {"key":"practice/s-599008555ed60dda","state":{"route":"practice/s-599008555ed60dda"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\"><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\" open><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\" aria-current=\"page\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\"><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\"><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2023 副省级 申论#2":"10688752da04f8c67a221b3a","国考 2024 副省级 申论#3":"10688752da04f8c67a221b3a","国考 2024 地市级 申论#2":"10688752da04f8c67a221b3a","国考 2024 行政执法 申论#2":"5b58f000836c3910403a3fd1","江苏 2024 C类 申论#2":"5b58f000836c3910403a3fd1"},"questions":{"国考 2023 副省级 申论#2":{"paper":"国考 2023 副省级 申论","n":2,"mod":"申论","src":["1b62f4f7aa551cdd783e.pdf",4],"asrc":["269b01c80926c8585ace.pdf",1]},"国考 2024 副省级 申论#3":{"paper":"国考 2024 副省级 申论","n":3,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",2]},"国考 2024 地市级 申论#2":{"paper":"国考 2024 地市级 申论","n":2,"mod":"申论","src":["a79e2681008a994c88a1.pdf",4],"asrc":["a3a840c0e3e8755b8daa.pdf",1]},"国考 2024 行政执法 申论#2":{"paper":"国考 2024 行政执法 申论","n":2,"mod":"申论","src":["b9a9a500aad1608fddd0.pdf",4],"asrc":["b899d5c3aecda01e69ec.pdf",1]},"江苏 2024 C类 申论#2":{"paper":"江苏 2024 C类 申论","n":2,"mod":"申论","src":["a7cfdee83e6ff0de5e71.pdf",3],"asrc":["525cbf0b49bf46168baf.pdf",1]}},"first":{"qs":{"国考 2023 副省级 申论#2":{"paper":"国考 2023 副省级 申论","n":2,"mod":"申论","src":["1b62f4f7aa551cdd783e.pdf",4],"asrc":["269b01c80926c8585ace.pdf",1],"m":["6d2639fbbe599f9a"],"task":"根据给定资料2，分析窑洞修复过程中村民从旁观者到参与者再到传承者的各阶段成因。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是材料所述的修复过程和村民行为变化，贺词与党的二十大报告属于参观叙事背景。"},"links":[{"id":"k-6b64b7cb17cae44e","label":"文化遗产价值认同有助于促成村民参与修复","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"让村民认识窑洞的历史价值，认同建筑风格，由此开始支持修复工","why":"影像展增进村民对窑洞价值和原有风格的认同，解释了他们为何转向主动参与。","origin":"逐题标记"},{"id":"k-930be7be8e1befce","label":"村民可通过义务讲解传承乡土文化","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"一些村民也成为了义务宣讲员","why":"修复后村民向游客讲述窑洞历史，说明他们如何承担文化传承角色。","origin":"逐题标记"},{"id":"s-599008555ed60dda","label":"按角色变化阶段归纳材料中的成因","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"分别给出了村民成为“旁观者”“参与者”“传承者”的","why":"以角色转变为线索，从材料中提取并分条归纳各阶段的成因和行为依据。","origin":"逐题标记"}],"stem":"请你根据“给定资料2”，谈谈为什么“有村民说，窑洞修复的过程，也是他们从旁观者变成参与者再到传承者的过\n程”。（15分）\n要求：分析全面，条理清晰。不超过250字。","options":[],"answer":"","analysis":"因为窑洞修复中工作方式的变化，确实导致了村民角色的变化。\n    1.一开始是旁观者，因为：修复工作由村委会发起，专家团队负责，未要求村民参与；且这一阶段村民缺少修复\n知识，甚至对修复方式和效果不理解。\n    2.后来变为参与者，因为：村里举办影像展，让村民认识窑洞的历史价值，认同建筑风格，由此开始支持修复工\n作，踊跃捐献旧建材、出谋划策，还以义务劳动的形式参与修复工作。\n    3.最后变成传承者，因为：随着修复推进，村民以言行让工匠师傅认识到修复工作的意义；修复项目结束后，村\n民成为义务宣讲员，向游客讲述窑洞历史。\n    参考答案说明：本参考答案先解释了题干给定句子的含义，再分别给出了村民成为“旁观者”“参与者”“传承者”的\n原因，进行了分类、分条撰写。各条要点彼此独立、没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["文化","社会治理"],"nature":"综合题","current":false},"国考 2024 副省级 申论#3":{"paper":"国考 2024 副省级 申论","n":3,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",2],"m":["d2f9c6b742757876"],"task":"根据材料3，分析小李想转行却难以下决心的原因，并提出走出职业困境的对策，作答不超过350字。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依赖材料中的行业变化和人物经历，无须知道窗口内的具体事件或政策部署。"},"links":[{"id":"k-65513b70ecd2968b","label":"新能源汽车市场扩张对单一业务发动机供应商的冲击","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"M1","quote":"业务单一的A公司也“一损俱损”","why":"客户销售承压会传导至业务单一的供应商，解释了小李对留任风险的担忧。","origin":"逐题标记"},{"id":"k-a4c47c76e91c3bbe","label":"职业转型需综合权衡收入、工作强度和专业兴趣","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"尽管薪酬提升了30%，但工作量增加了不止","why":"小沈的经历说明加薪可能伴随工作强度上升，小王的选择则说明专业兴趣也是择业依据。","origin":"逐题标记"},{"id":"k-e4331723eb1e2f93","label":"内燃机在商用车领域仍有应用空间","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"在商用车领域仍有用武之地","why":"材料以重型车辆纯电方案的电池需求和成本约束解释内燃机仍有价值，为判断职业前景提供依据。","origin":"逐题标记"},{"id":"k-4170c6524068d884","label":"内燃机从业经验可迁移至新能源汽车岗位","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"内燃机与电动机的理念、技术相通","why":"动力系统相关理念和技术相通，支持以既有经验降低转岗适应难度的判断。","origin":"逐题标记"},{"id":"s-599008555ed60dda","label":"按相反决策方向归纳两难成因","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"分别给出了小李想转行和难以","why":"按促使转行和阻碍转行两个方向组织原因，解释当事人为何犹豫不决。","origin":"逐题标记","originalId":"s-03c77e9470d4a197"},{"id":"s-ecba3f8c2c1d3b9b","label":"用材料中的对照案例提炼针对性对策","catalog_id":null,"type":null,"role":"直接考查","field":"M1","quote":"小王并没有因为新能源汽车的快速发展而感到焦虑","why":"从小王的择业经历和行业判断中提取可用于化解小李困境的做法。","origin":"逐题标记","originalId":"s-498b6f865147ddc0"}],"stem":"“给定材料3”中提到，小李感觉自己陷入了“两难”境地。请分析小李产生这种心态的原因，并提出走出这种困境的\n对策。（15分）\n要求：分析全面、对策得当、逻辑清晰，不超过350字。","options":[],"answer":"","analysis":"小李的“两难”境地是既想转行，又难以下决心，是受汽车产业转型大环境影响而产生的焦虑心态。\n  一、其原因是：1.想转行是因为：新能源汽车行业市场规模快速扩大，薪酬待遇更高，发展前景更好；传统车企\n销售压力增大，业务萎缩，行业裁员、关停、转型多发；所在公司大量同事离职，职业荣光褪色，自己面临被裁员\n的风险。2.难以下决心是因为：新能源汽车行业工作氛围内卷，工作量相较太重；公司短期内没有倒闭风险，收入相\n对稳定，工作氛围宽松。\n  二、对策：转变观念。1.主动选择行业。相较薪酬，要更关注自己感兴趣的专业；在踏实工作中积累经验。2.了\n解行业趋势。内燃机市场短期内不会消失，在商用车领域仍有用武之地；行业正联手布局氢内燃机。3.充分建立自\n信。认识到内燃机与电动机的理念、技术相通，且逻辑更复杂，有工作经验即便转行也能更快适应。\n  参考答案说明：本参考答案先解释了“小李感觉自己陷入了‘两难’境地”的含义，再分别给出了小李想转行和难以\n下定决心的原因，最后说明应转变观念，具体从“主动选择行业”“了解行业趋势”“充分建立自信”三个方面给出了对\n策，进行了分类、分条撰写。各条要点彼此独立、没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["经济","科技"],"nature":"综合题","current":false},"国考 2024 地市级 申论#2":{"paper":"国考 2024 地市级 申论","n":2,"mod":"申论","src":["a79e2681008a994c88a1.pdf",4],"asrc":["a3a840c0e3e8755b8daa.pdf",1],"m":["1853a18665042e24"],"task":"依据给定资料2，在300字以内归纳隆金公司何以从汽车配件供应商成长为市场中的主角。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答所需的企业经营举措和地方产业扶持条件均由材料提供，题目要求归纳企业成长原因。"},"links":[{"id":"k-81fbbd1305e0c3d7","label":"深耕细分市场有助于制造企业形成专业化竞争优势","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"三十多年深耕汽车配件领域，将产品做到行业顶尖","why":"长期专注汽车配件使隆金形成产品优势，并能进一步开拓高端、新能源和国际市场。","origin":"逐题标记"},{"id":"k-1cb22e7f8a8f4b40","label":"制造企业可将自动化设备与整车厂管理体系结合以推进精益管理","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"将自身硬实力与整车厂软实力相结合，实现精益化管理","why":"将设备能力与整车厂管理经验结合，解释了隆金如何改善开发、供应和产能管理。","origin":"逐题标记"},{"id":"k-2648d9806bee5091","label":"持续质量攻关有助于汽车配件企业提升产品质量","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"组建质量改进团队、收集各种质量问题信息、实施质量改进措施","why":"专门团队收集问题并落实改进措施，解释了隆金如何持续保证配件质量。","origin":"逐题标记"},{"id":"k-ebf165412205315f","label":"数字化生产与研发人才建设有助于制造企业降本增效和提升创新能力","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"建设数字化车间、智能工厂，降本增效；建立海外研发中心，吸引创新人才","why":"数字化车间提高生产效率、降低运营成本，研发平台和校企合作为技术创新提供人才支撑。","origin":"逐题标记"},{"id":"k-4df31a525ea73d9e","label":"制造业产业集群与地方企业培育政策为中小企业成长提供支撑","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"地方具有门类齐全的制造业体系和产业集群；政府建立企业培育库","why":"当地制造业基础和政府培育措施共同构成隆金成长的外部条件。","origin":"逐题标记"},{"id":"s-599008555ed60dda","label":"从案例材料中提取并分类归纳成功原因","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"紧扣资料，归纳准确","why":"需从企业发展事例中筛选能够解释其市场地位的做法和外部条件，将同类信息合并为并列要点。","origin":"逐题标记","originalId":"s-1d330d9ae1883bee"}],"stem":"“给定资料2”中，隆金公司虽然做的是配件，但也成为了市场中的主角。请你谈谈隆金公司为什么能成为“市场中\n的主角”。（15分）\n要求：\n（1）紧扣资料，归纳准确；\n（2）内容全面，条理清晰；\n（3）不超过300字。","options":[],"answer":"","analysis":"1.始终保持专注。三十多年深耕汽车配件领域，将产品做到行业顶尖；基于行业挖掘细分市场，深度拓展高端、\n新能源、国际汽车市场。\n   2.管理严格科学。生产程序严格；将自身硬实力与整车厂软实力相结合，实现精益化管理；借由申获“市长质量\n奖”，提升经营和质量管理。\n   3.产品质量过硬。坚持进行质量攻关，组建质量改进团队、收集各种质量问题信息、实施质量改进措施，不断进\n行研发创新与技术迭代。\n   4.技术实力雄厚。建设数字化车间、智能工厂，降本增效；建立海外研发中心，吸引创新人才；与知名高校合作\n培养技术能手和行业专家。\n   5.产业支撑有力。地方具有门类齐全的制造业体系和产业集群；政府建立企业培育库，出台一系列政策文件，推\n动企业发展壮大。\n   参考答案说明：本参考答案从“始终保持专注”“管理严格科学”“产品质量过硬”“技术实力雄厚”“产业支撑有力”五个\n方面展开，各条答案要点之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["经济","科技"],"nature":"综合题","current":false}},"materialFiles":{"6d2639fbbe599f9a":"c2995e6fc0472ac4f38f95e1","d2f9c6b742757876":"72e97cf575ec9838d2914f45","1853a18665042e24":"0a41a34ca93e3b999e76c666"},"terms":{"k-6b64b7cb17cae44e":{"id":"k-6b64b7cb17cae44e","mode":"k","type":"原理与机制","title":"开窑村村民从旁观到参与修复","qs":[],"count":1},"k-930be7be8e1befce":{"id":"k-930be7be8e1befce","mode":"k","type":"事实与事件","title":"开窑村村民义务宣讲窑洞文化","qs":[],"count":1},"s-599008555ed60dda":{"id":"s-599008555ed60dda","mode":"s","type":"综合分析","title":"分析现象形成的原因","qs":[],"count":5},"k-65513b70ecd2968b":{"id":"k-65513b70ecd2968b","mode":"k","type":"原理与机制","title":"整车销售承压向发动机供应商传导","qs":[],"count":1},"k-a4c47c76e91c3bbe":{"id":"k-a4c47c76e91c3bbe","mode":"k","type":"观点与论证","title":"职业转型中的薪酬、工作强度与专业兴趣","qs":[],"count":1},"k-e4331723eb1e2f93":{"id":"k-e4331723eb1e2f93","mode":"k","type":"观点与论证","title":"内燃机在商用车领域的应用前景","qs":[],"count":1},"k-4170c6524068d884":{"id":"k-4170c6524068d884","mode":"k","type":"观点与论证","title":"内燃机从业经验向新能源汽车岗位迁移","qs":[],"count":1},"s-ecba3f8c2c1d3b9b":{"id":"s-ecba3f8c2c1d3b9b","mode":"s","type":"提出对策","title":"将外地经验转化为本地措施","qs":[],"count":6},"k-81fbbd1305e0c3d7":{"id":"k-81fbbd1305e0c3d7","mode":"k","type":"事实与事件","title":"深耕汽车配件市场","qs":[],"count":1},"k-1cb22e7f8a8f4b40":{"id":"k-1cb22e7f8a8f4b40","mode":"k","type":"原理与机制","title":"隆金公司的精益化管理","qs":[],"count":2},"k-2648d9806bee5091":{"id":"k-2648d9806bee5091","mode":"k","type":"方法与技能","title":"汽车配件质量攻关","qs":[],"count":2},"k-ebf165412205315f":{"id":"k-ebf165412205315f","mode":"k","type":"事实与事件","title":"隆金公司的数字化生产与研发人才建设","qs":[],"count":1},"k-4df31a525ea73d9e":{"id":"k-4df31a525ea73d9e","mode":"k","type":"事实与事件","title":"制造业产业集群与企业培育政策","qs":[],"count":1}},"questions":{}},"firstMaterials":[{"key":"6d2639fbbe599f9a","value":["材料2","材料2\n  “大家以前对窑洞有些什么印象？”开窑村的村委委员小辛问。\n\n  “习近平总书记在给全国人民的新年贺词中，提到了当年毛主席与黄炎培先生的‘窑洞对’。如何跳出治乱兴衰的历\n史周期率？毛主席给出了第一个答案，让人民来监督政府。现在我们党给出第二个答案，自我革命。在党的二十大\n报告中，也再次提到这一重要论断。‘窑洞对’，是我对窑洞最深刻的印象。”\n  “提到窑洞，脑海中浮现的画面就是黄土地、高山坡，挖个洞在里面住着，想到就觉得特别艰苦。”\n  “窑洞已有4000多年的历史，它不仅是我们祖祖辈辈的栖身之地，也曾是红军的驻地……”小辛向游客娓娓讲述有\n关窑洞的悠久历史和红色岁月。前来参观的游客们纷纷谈起自己的感受，来到黄河岸边、大山深处，面对着300孔隐\n在群山中层层叠叠错落有致的窑洞，即使现如今这里已经被改造成文化教育基地，游客们依然能想象出革命战争年\n代窑洞中的艰苦景象。\n  参观行程过半，有位游客问小辛：“你们当时是怎么想起把这些窑洞打造成文化教育基地的？”\n  小辛说：“经济条件好了，我们也陆续住进新盖的房子，大部分窑洞被废弃。但是我们内心非常不愿意窑洞就这\n么消失。因为我们世世代代都曾经居住在窑洞里，窑洞对于我们来说，是血脉，也是乡愁。”\n  小辛想到了7年前，那时候村委会正打算让这些“沉睡的资产”焕发出新的生机。村委会找到了某大学建筑学院的\n顾教授团队负责窑洞修复项目。顾教授团队和村委会多次协商，反复讨论，最终达成一致意见：修复窑洞要尽量保\n留自然地貌，以及窑洞和院落的本来面貌。因此，修复工程使用的建筑材料都是废弃的砖瓦、石头、旧门窗、破碎\n的缸罐等。\n  小辛还记得，当时他在读大学，回家看望父母时，村民们找到他，说他有文化，让他代表村民们去和顾教授沟\n通。“小辛啊，你看，这些旧材料是挺省钱的，但是费时费工啊，我们啥时候能修好呢？而且修好了，这不和以前一\n个样吗？还是灰蒙蒙的。修就修得好看一点嘛！”\n  面对村民们的不理解，小辛主动找到村委会工作人员，还邀请了一些村民代表，协商共议后，在村里举办了“发\n现砖石之美”影像展。这让村民们重新认识到窑洞建筑的历史价值，也更加认同窑洞原本的建筑风格。“这是我们永恒\n的记忆符号，也是独特的文化标识。废旧材料本身就凝结着村庄的历史与个体的记忆，是新的建筑材料无法替代\n的。”小辛说。\n  村民们从否定变成了支持，开始踊跃捐献家中的旧建材。不少人主动问：“我们家里就有很多旧砖旧瓦啊，你们\n施工还要不要？”村里的王大娘早年丧夫，曾经过得很艰辛。生活好转离开窑洞老屋时，她爬上屋顶将瓦小心地逐片\n剥落，并保存了30多年。她找到顾教授，把这些瓦都捐了出来，说：“现在日子好了，没想到这些旧瓦片还能再派上\n用场，捐给你们比搁我手里强！”\n  施工期间，小辛组织村民们去工地观看。“这里是我捐出的砖。”“这个角落里的图案，有我家孩子拿来的玻璃\n球。”“这里可以用碎瓦片砌成‘花墙’。”村民们饶有兴趣地指指点点，还不时出谋划策。小辛还带领村民们发起了多次\n义务劳动，上山采石、填坑铺地、为工地运送物资、向工匠师傅嘘寒问暖，以实际行动支持窑洞修复项目。\n  村民的“言”和“行”慢慢渗透进修复窑洞的师傅们心里，他们也不再着急赶工，开始思考怎么能更好地把顾教授团\n队的方案、村民们的灵感和他们的手艺融合起来。老郑，这个从业30余年的工匠师傅说：“刚来时，一看在深山里，\n心里嘀咕这次肯定特别苦。但是施工过程中，通过和顾教授他们接触，和开窑村的村民闲聊，我才知道原来窑洞还\n有这么多说法，窑洞文化的历史这么悠久。一下子就让我们这些泥土匠的活有了意义！再苦心也甜！”\n  窑洞修复项目的结束，意味着文化教育基地新的工作的开始。恰逢小辛大学毕业，他被村里留下，担任村委委\n员，开始承担文化教育基地的宣传推广工作。一些村民也成为了义务宣讲员，他们每每谈起村里的窑洞，都特别骄\n傲。“当时窑洞修复花了一年多才完成。有村民说，窑洞修复的过程，也是他们从旁观者变成参与者再到传承者的过\n程。”小辛感慨道。",["1b62f4f7aa551cdd783e.pdf",1]],"label":"国考 2023 副省级 申论|材料2"}],"node":{"id":"s-599008555ed60dda","mode":"s","title":"分析现象形成的原因","type":"综合分析","domain":"文化","reading":"","intro":"","priority":100,"aliases":["按角色变化阶段归纳材料中的成因","按相反决策方向归纳两难成因","从案例材料中提取并分类归纳成功原因","提取案例成因并按并列维度归纳","从案例中归纳措施及其促成行为转变的原因"],"qs":["国考 2023 副省级 申论#2","国考 2024 副省级 申论#3","国考 2024 地市级 申论#2","国考 2024 行政执法 申论#2","江苏 2024 C类 申论#2"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"subject":"申论","publishedSets":[{"name":"分析现象形成的原因","ids":["国考 2023 副省级 申论#2","国考 2024 副省级 申论#3","国考 2024 地市级 申论#2","国考 2024 行政执法 申论#2","江苏 2024 C类 申论#2"],"units":[["国考 2023 副省级 申论#2"],["国考 2024 副省级 申论#3"],["国考 2024 地市级 申论#2"],["国考 2024 行政执法 申论#2"],["江苏 2024 C类 申论#2"]]}]}};
